private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }
    TreeNode<T> leftChild = node.getLeft();
    if (leftChild == null) {
        return node; // nothing to rotate
    }
    // detach left child
    node.setLeft(leftChild.getRight());
    if (leftChild.getRight() != null) {
        leftChild.getRight().setParent(node);
    }
    // attach node as right child of left child
    leftChild.setRight(node);
    leftChild.setParent(node.getParent());
    node.setParent(leftChild);
    // reconnect with grandparent
    if (leftChild.getParent() != null) {
        if (leftChild.getParent().getLeft() == node) {
            leftChild.getParent().setLeft(leftChild);
        } else if (leftChild.getParent().getRight() == node) {
            leftChild.getParent().setRight(leftChild);
        }
    }
    return leftChild;
}

