        throw new IllegalArgumentException("target and resultMap must not be null");
    }
    // Add all vertices to the target graph if they are not already present
    for (V v : resultMap.values()) {
        if (!target.containsVertex(v)) {
            target.addVertex(v);
        }
    }
    // Build a list of vertices for easy indexing
    java.util.List<V> vertices = new java.util.ArrayList<>(resultMap.values());
    int total = vertices.size();
    if (total < 2) {
        return; // Not enough vertices to form a bipartite edge set
    }
    int half = total / 2;
    java.util.List<V> left = vertices.subList(0, half);
    java.util.List<V> right = vertices.subList(half, total);
    // Create complete bipartite connections between left and right partitions
    for (V u : left) {
        for (V v : right) {
            try {
                if (!target.containsEdge(u, v) && !target.containsEdge(v, u)) {
                    target.addEdge(u, v);
                }
            } catch (Exception ignored) {
                // Edge creation might fail if vertices are not accepted by the graph
            }
        }
    }
}

