        result[i] = cls;
    }
    return result;
}

/**
 * Attempts to locate the type argument mapping for the targetType within the genericType's hierarchy.
 */
private static boolean findTypeArguments(Class<?> current, Class<?> target, ParameterizedType currentPType,
        Map<TypeVariable<?>, Type> map) {
    if (current == target) {
        // Map target's type variables to the current type's actual arguments
        TypeVariable<?>[] targetParams = target.getTypeParameters();
        Type[] actualArgs = currentPType.getActualTypeArguments();
        for (int i = 0; i < targetParams.length && i < actualArgs.length; i++) {
            map.put(targetParams[i], actualArgs[i]);
        }
        return true;
    }
    // Check interfaces
    Type[] genericInterfaces = current.getGenericInterfaces();
    for (Type ti : genericInterfaces) {
        if (ti instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) ti;
            Class<?> ifaceRaw = (Class<?>) pt.getRawType();
            if (findTypeArguments(ifaceRaw, target, pt, map)) {
                // map overwritten with the most specific mapping
                return true;
            }
        } else if (ti instanceof Class<?>) {
            Class<?> iface = (Class<?>) ti;
            if (findTypeArguments(iface, target, null, map)) {
                return true;
            }
        }
    }
    // Check superclass
    Type genericSuperclass = current.getGenericSuperclass();
    if (genericSuperclass instanceof ParameterizedType) {
        ParameterizedType ps = (ParameterizedType) genericSuperclass;
        Class<?> superRaw = (Class<?>) ps.getRawType();
        if (findTypeArguments(superRaw, target, ps, map)) {
            return true;
        }
    } else if (genericSuperclass instanceof Class<?>) {
        Class<?> superClass = (Class<?>) genericSuperclass;
        if (findTypeArguments(superClass, target, null, map)) {
            return true;
        }
    }
    return false;
}

/**
 * Resolves a Type to a Class, handling ParameterizedType, Class, WildcardType, and GenericArrayType.
 */
private static Class<?> resolveToClass(Type type) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    }
    if (type instanceof WildcardType) {
        WildcardType wt = (WildcardType) type;
        Type[] upper = wt.getUpperBounds();
        if (upper.length == 1) {
            return resolveToClass(upper[0]);
        }
    }
    if (type instanceof TypeVariable<?>) {
        // Try to get first bound as a fallback
        TypeVariable<?> tv = (TypeVariable<?>) type;
        Type[] bounds = tv.getBounds();
        if (bounds.length == 1) {
            return resolveToClass(bounds[0]);
        }
    }
    if (type instanceof GenericArrayType) {
        // Cannot determine component type at runtime
        return null;
    }
    return null;
}

