        return;
    }
    // Place the event into the buffer
    buffer[writeIndex] = o;
    writeIndex = (writeIndex + 1) % capacity;
    size++;
}

public void put(LoggingEvent o){
    if (o == null) {
        return;
    }
    try {
        // Attempt to add the event to the buffer only if there is free space.
        if (buffer instanceof java.util.concurrent.BlockingQueue<?>) {
            java.util.concurrent.BlockingQueue<LoggingEvent> bq = (java.util.concurrent.BlockingQueue<LoggingEvent>) buffer;
            if (bq.remainingCapacity() > 0) {
                bq.offer(o);
            }
        } else if (buffer instanceof java.util.Queue<?>) {
            java.util.Queue<LoggingEvent> q = (java.util.Queue<LoggingEvent>) buffer;
            // For ordinary queues we just offer; if it cannot hold, the element is discarded.
            q.offer(o);
        } else {
            // Fallback: try invoking an add method via reflection.
            java.lang.reflect.Method add = buffer.getClass().getMethod("add", LoggingEvent.class);
            add.invoke(buffer, o);
        }
    } catch (Exception ignore) {
        // Silently drop the event if the buffer is full or any other error occurs.
    }
}

protected List<TimeRange> buildTimeRanges(long start,long end){
