static long compressTimeBucket(long timeBucket,int dayStep){
    try {
        String s = Long.toString(timeBucket);
        if (s.length() != 8) return timeBucket;
        int year  = Integer.parseInt(s.substring(0, 4));
        int month = Integer.parseInt(s.substring(4, 6));
        int day   = Integer.parseInt(s.substring(6, 8));
        java.time.LocalDate date = java.time.LocalDate.of(year, month, day);
        if (dayStep <= 0) return timeBucket;
        int newDay = ((day - 1) / dayStep) * dayStep + 1;
        // Make sure newDay is valid for the month
        int maxDay = date.lengthOfMonth();
        if (newDay > maxDay) newDay = maxDay;
        java.time.LocalDate newDate = date.withDayOfMonth(newDay);
        return newDate.getYear() * 10000L + newDate.getMonthValue() * 100L + newDate.getDayOfMonth();
    } catch (Exception e) {
        return timeBucket;
    }
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        return timeBucket;
    }
    int year  = (int)(timeBucket / 10000);
    int month = (int)((timeBucket / 100) % 100);
    int day   = (int)(timeBucket % 100);
    if(month < 1 || month > 12 || day < 1){
        return timeBucket;
    }
    int daysInMonth;
    switch(month){
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            daysInMonth = 31;
            break;
        case 4: case 6: case 9: case 11:
            daysInMonth = 30;
            break;
        case 2:
            boolean leap = (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0));
            daysInMonth = leap ? 29 : 28;
            break;
        default:
            return timeBucket;
    }
    if(day > daysInMonth){
        return timeBucket;
    }
    int bucketDay = ((day - 1) / dayStep) * dayStep + 1;
    if(bucketDay > daysInMonth){
        bucketDay = daysInMonth;
    }
    return year * 10000L + month * 100L + bucketDay;
}

