public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (index < 0 || len < 0 || index > str.length() - len) {
        throw new IndexOutOfBoundsException("index=" + index + ", len=" + len + ", length=" + str.length());
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
            i++;
        } else if (ch <= 0x7FF) {
            size += 2;
            i++;
        } else if (ch >= 0xD800 && ch <= 0xDBFF) { // high surrogate
            if (i + 1 >= end) {
                throw new IllegalArgumentException("Unpaired high surrogate at index " + i);
            }
            char low = str.charAt(i + 1);
            if (low >= 0xDC00 && low <= 0xDFFF) {
                size += 4;
                i += 2;
            } else {
                throw new IllegalArgumentException("Unpaired high surrogate at index " + i);
            }
        } else if (ch >= 0xDC00 && ch <= 0xDFFF) {
            throw new IllegalArgumentException("Unpaired low surrogate at index " + i);
        } else {
            size += 3;
            i++;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if(str==null) throw new NullPointerException("str");
    int strLen=str.length();
    if(index<0 || index>strLen) throw new IndexOutOfBoundsException("index out of bounds");
    if(len<0 || index+len>strLen) throw new IndexOutOfBoundsException("len out of bounds");
    int end=index+len;
    int utf8Len=0;
    for(int i=index;i<end;){
        char ch=str.charAt(i);
        int cp;
        if(Character.isHighSurrogate(ch) && i+1<end){
            char l=str.charAt(i+1);
            if(Character.isLowSurrogate(l)){
                cp=Character.toCodePoint(ch,l);
                i+=2;
            }else{
                cp=ch;
                i++;
            }
        }else{
            cp=ch;
            i++;
        }
        if(cp<=0x7F) utf8Len+=1;
        else if(cp<=0x7FF) utf8Len+=2;
        else if(cp<=0xFFFF) utf8Len+=3;
        else if(cp<=0x10FFFF) utf8Len+=4;
        else throw new IllegalArgumentException("Invalid Unicode code point: "+cp);
        if(utf8Len<0) throw new ArithmeticException("UTF-8 size overflow");
    }
    return utf8Len;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len){
    if (str == null) {
        throw new IllegalArgumentException("str is null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("index or length out of bounds");
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            // surrogate pair represents a BMP supplement (4 bytes in UTF‑8)
            size += 4;
            i++; // skip low surrogate
        } else if (Character.isLowSurrogate(ch)) {
            // lone low surrogate; treat as 3 bytes per Java’s encoding of malformed surrogates
            size += 3;
        } else {
            size += 3;
        }
        i++;
    }
    return size;
}

