public static String sub(String str,int start,int end){
    if(str==null){
        return null;
    }
    int len = str.length();
    if(len==0){
        return "";
    }
    // Adjust bounds
    int s = Math.max(0, start);
    int e = Math.min(len, end);
    if(s>e){
        return "";
    }
    try{
        return str.substring(s,e);
    }catch(IndexOutOfBoundsException ex){
        // As a fallback, adjust again
        s = Math.max(0, start);
        e = Math.min(len, end);
        if(s>e){
            return "";
        }
        return str.substring(s,e);
    }
}

