public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if (byteLength < 0) throw new IllegalArgumentException("byteLength must be >= 0");
    int newPos = pos + byteLength;
    if (newPos > buf.length) {
        byte[] newBuf = new byte[Math.max(buf.length * 2, newPos)];
        System.arraycopy(buf, 0, newBuf, 0, pos);
        buf = newBuf;
    }
    if (byteArrayValue == null) {
        // fill with null bytes (0)
        for (int i = pos; i < newPos; i++) buf[i] = 0;
    } else {
        if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length)
            throw new IllegalArgumentException("byteOffset and byteLength out of bounds");
        System.arraycopy(byteArrayValue, byteOffset, buf, pos, byteLength);
    }
    pos = newPos;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate arguments
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteArrayValue == null) {
        // Write nullbytes
        for (int i = 0; i < byteLength; i++) {
            putByte((byte) 0);
        }
        return this;
    }
    if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset and byteLength out of bounds for the provided array");
    }
    // Ensure internal capacity
    ensureCapacity(size + byteLength);
    // Copy bytes into the internal buffer
    System.arraycopy(byteArrayValue, byteOffset, buffer, size, byteLength);
    size += byteLength;
    return this;
}

