public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    if(lb == null){
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    if(str == null || str.length() == 0){
        return lb;
    }
    // Convert the character sequence to UTF-8 encoded bytes
    byte[] utf8Bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
    try{
        // Write the bytes to the LinkedBuffer in one go
        lb.writeBytes(utf8Bytes, 0, utf8Bytes.length);
    }catch(Exception e){
        // Fallback: write byte by byte if bulk write fails
        for(byte b : utf8Bytes){
            lb.writeByte(b);
        }
    }
    return lb;
}

