    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    if (suffix.length() > str.length()) {
        return false;
    }
    if (ignoreCase) {
        String strLower = str.toLowerCase();
        String suffixLower = suffix.toLowerCase();
        return strLower.endsWith(suffixLower);
    } else {
        return str.endsWith(suffix);
    }
}

