    if (str == null) return suffix == null;
    if (suffix == null) return false;
    int slen = suffix.length();
    if (slen > str.length()) return false;
    return str.regionMatches(ignoreCase, str.length() - slen, suffix, 0, slen);
}

private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){
    if (str == null && suffix == null) return true;
    if (str == null || suffix == null) return false;
    if (suffix.length() > str.length()) return false;
    if (ignoreCase) {
        return str.regionMatches(true, str.length() - suffix.length(), suffix, 0, suffix.length());
    } else {
        return str.endsWith(suffix);
    }
}

private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){
    if(str == null){
        return suffix == null; // both null -> true, otherwise false
    }
    if(suffix == null){
        return false; // str is not null
    }
    int suffixLength = suffix.length();
    int strLength = str.length();
    if(suffixLength > strLength){
        return false;
    }
    if(ignoreCase){
        return str.regionMatches(true, strLength - suffixLength, suffix, 0, suffixLength);
    }else{
        return str.substring(strLength - suffixLength).equals(suffix);
    }
}

