@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure that the target type is Character (or primitive char)
    if (value == null) {
        return null;
    }
    if (!Character.class.equals(type) && !type.equals(char.class)) {
        throw new IllegalArgumentException(
                "Target type must be java.lang.Character or primitive char");
    }

    // If the value is already a Character, just return it
    if (value instanceof Character) {
        return value;
    }

    // If it's a CharSequence with exactly one character
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return new Character(cs.charAt(0));
        }
        throw new IllegalArgumentException(
                "Cannot convert CharSequence of length " + cs.length() + " to Character");
    }

    // If it's a Number, interpret its integer value as a Unicode code point
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
            throw new IllegalArgumentException(
                    "Numeric value " + intVal + " is out of the Character range");
        }
        return new Character((char) intVal);
    }

    // Fallback: use the string representation
    String str = value.toString();
    if (str.length() == 1) {
        return new Character(str.charAt(0));
    }

    throw new IllegalArgumentException("Cannot convert value [" + value + "] to Character");
}

