        if (n % i == 0 || n % (i + 2) == 0) return false;
        i += 6;
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Ensure odd number to check
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    // Upper bound to avoid infinite loop if max int reached
    while (candidate >= 0) { // integer overflow check
        if (isPrime(candidate)) {
            return candidate;
        }
        // Skip even numbers
        candidate += 2;
    }
    // If overflowed, return Integer.MAX_VALUE if prime or 0 otherwise
    return (isPrime(Integer.MAX_VALUE)) ? Integer.MAX_VALUE : 0;
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    int sqrt = (int) Math.sqrt(n);
    for (int i = 5; i <= sqrt; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

