private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    if (jsonObject == null) {
        return content;
    }
    for (String key : jsonObject.keySet()) {
        try {
            JsonValue value = jsonObject.get(key);
            switch (value.getValueType()) {
                case STRING:
                    content.put(key, ((JsonString)value).getString());
                    break;
                case NUMBER:
                    JsonNumber num = (JsonNumber)value;
                    if (num.isIntegral()) {
                        content.put(key, num.longValue());
                    } else {
                        content.put(key, num.doubleValue());
                    }
                    break;
                case TRUE:
                case FALSE:
                    content.put(key, value == JsonValue.TRUE);
                    break;
                case NULL:
                    content.put(key, null);
                    break;
                case ARRAY:
                    // Convert JsonArray to List<Object>
                    List<Object> list = new ArrayList<>();
                    JsonArray ja = (JsonArray)value;
                    for (JsonValue v : ja) {
                        // simple conversion for each element
                        if (v.getValueType() == JsonValue.ValueType.STRING) {
                            list.add(((JsonString)v).getString());
                        } else if (v.getValueType() == JsonValue.ValueType.NUMBER) {
                            JsonNumber numVal = (JsonNumber)v;
                            list.add(numVal.isIntegral() ? numVal.longValue() : numVal.doubleValue());
                        } else if (v.getValueType() == JsonValue.ValueType.TRUE || v.getValueType() == JsonValue.ValueType.FALSE) {
                            list.add(v == JsonValue.TRUE);
                        } else if (v.getValueType() == JsonValue.ValueType.NULL) {
                            list.add(null);
                        } else {
                            // keep nested structure as-is
                            list.add(v);
                        }
                    }
                    content.put(key, list);
                    break;
                case OBJECT:
                    // keep nested JsonObject as-is
                    content.put(key, value);
                    break;
            }
        } catch (Exception e) {
            // For any unexpected type or error, store the raw JsonValue
            content.put(key, value);
        }
    }
    return content;
}

