private int computeBinaryLog(int n){
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int log = 0;
    while (n > 1) {
        n >>= 1;
        log++;
    }
    return log + 1;
}

private int computeBinaryLog(int n){ 
    if (n <= 0) { 
        throw new IllegalArgumentException("n must be positive"); 
    } 
    return 32 - Integer.numberOfLeadingZeros(n); 
}

private Set<V> intersection(Set<V> set1,Set<V> set2){
    // Handle null inputs
    if (set1 == null || set2 == null) {
        return new HashSet<V>();
    }
    // Quick return if either set is empty
    if (set1.isEmpty() || set2.isEmpty()) {
        return new HashSet<V>();
    }
    // Choose the smaller set for iteration to reduce lookups
    Set<V> small = set1.size() <= set2.size() ? set1 : set2;
    Set<V> large = set1.size() > set2.size() ? set1 : set2;
    Set<V> result = new HashSet<V>(Math.min(small.size(), large.size()));
    for (V element : small) {
        if (large.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

