    try{
        if(root == null){ return 0; }
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        java.util.Map<Category, Category> parentMap = new java.util.HashMap<>();
        stack.push(root);
        parentMap.put(root, null);
        while(!stack.isEmpty()){
            Category node = stack.pop();
            if(node == null){ continue; }
            if(!node.isActive()){
                Category parent = parentMap.get(node);
                if(parent == null){
                    // root node is inactive; nullify root
                    root = null;
                }else{
                    java.util.List<Category> siblings = parent.getChildren();
                    if(siblings != null){
                        siblings.remove(node);
                    }
                }
                removed++;
            }else{
                java.util.List<Category> children = node.getChildren();
                if(children != null){
                    for(Category child : children){
                        stack.push(child);
                        parentMap.put(child, node);
