        Deque<Category> stack = new ArrayDeque<>();
        Deque<Category> parentStack = new ArrayDeque<>();
        stack.push(root);
        parentStack.push(null); // Root has no parent
        while(!stack.isEmpty()){
            Category node = stack.pop();
            Category parent = parentStack.pop();
            // Process children first to avoid concurrent modification issues
            List<Category> children = node.getChildren();
            if(children != null){
                for(int i = children.size() - 1; i >= 0; i--){
                    stack.push(children.get(i));
                    parentStack.push(node);
