private int removeRecursive(Category node){
    int count = 0;
    java.util.Iterator<Category> it = node.getChildren().iterator();
    while(it.hasNext()){
        Category child = it.next();
        count += removeRecursive(child);
        if (!child.isActive()){
            it.remove();
            count++;
        }
    }
    return count;
}

