private String parseToken(final char[] terminators){
    // Validate input
    if (terminators == null) {
        throw new IllegalArgumentException("terminators array must not be null");
    }
    // Assume class has a char buffer and a current position index
    if (buffer == null) {
        throw new IllegalStateException("input buffer is not initialized");
    }

    int start = pos; // starting index of the token
    boolean stop = false;
    try {
        while (!stop && pos < buffer.length) {
            char current = buffer[pos];
            // Check if current character is one of the terminators
            for (char term : terminators) {
                if (current == term) {
                    stop = true;
                    break;
                }
            }
            if (!stop) {
                pos++; // consume character
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Error while parsing token", e);
    }

    // Extract token from buffer. If start == pos, token is empty.
    return new String(buffer, start, pos - start);
}

private String parseToken(final char[] terminators){
    if (input == null) {
        return "";
    }
    int start = pos;
    int length = input.length();
    while (pos < length) {
        char c = input.charAt(pos);
        boolean isTerm = false;
        if (terminators != null) {
            for (char t : terminators) {
                if (c == t) {
                    isTerm = true;
                    break;
                }
            }
        }
        if (isTerm) {
            break;
        }
        pos++;
    }
    if (start == pos) {
        return "";
    }
    return input.substring(start, pos);
}

