public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null) {
        throw new IllegalArgumentException("Buffer must not be null");
    }
    // Assume the full name is stored in a field called 'name'.
    String name = this.name;
    if (name == null || name.isEmpty()) {
        return;
    }
    int start = nameStart;
    if (start < 0) {
        start = 0;
    }
    int length = name.length();
    if (start >= length) {
        return;
    }
    int idx = start;
    while (idx < length) {
        int nextDot = name.indexOf('.', idx);
        if (nextDot == -1) {
            nextDot = length;
        }
        if (nextDot == length) {
            // Last part – append it fully.
            buf.append(name.substring(idx));
            break;
        } else {
            // Abbreviate this part.
            buf.append(name.charAt(idx));
            buf.append('.');
            idx = nextDot + 1;
        }
    }
}

