                } else { 
                    next++; 
                } 
                idx = next; 
                outputFrameStack.pop(); 
            } 
            idx++; 
        } else { 
            int next = idx; 
            char ch = descriptor.charAt(next); 
            while (ch == '[') { 
                next++; 
                ch = descriptor.charAt(next); 
            } 
            if (ch == 'L') { 
                next = descriptor.indexOf(';', next) + 1; 
            } else { 
                next++; 
            } 
            idx = next; 
            outputFrameStack.pop(); 
        } 
    } catch (Exception e) { 
        // ignore or log malformed descriptor 
    } 
}

