public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return null;
    }
    // If the relativePath is actually an absolute path, just normalize it
    java.io.File relFile = new java.io.File(relativePath);
    if (relFile.isAbsolute()) {
        try {
            return relFile.getCanonicalPath();
        } catch (java.io.IOException e) {
            return relFile.getAbsolutePath();
        }
    }
    // Determine base directory: if path refers to a file, use its parent
    java.io.File base = new java.io.File(path);
    if (!base.isDirectory()) {
        java.io.File parent = base.getParentFile();
        if (parent != null) {
            base = parent;
        } else {
            // No parent, treat current directory as base
            base = new java.io.File(".");
        }
    }
    java.io.File result = new java.io.File(base, relativePath);
    try {
        return result.getCanonicalPath();
    } catch (java.io.IOException e) {
        return result.getAbsolutePath();
    }
}

