public static String applyRelativePath(String path,String relativePath){
    if (path == null) {
        throw new IllegalArgumentException("path must not be null");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    boolean absolute = path.startsWith("/");
    // Concatenate path and relativePath ensuring a single separator
    String combined = path;
    if (!combined.endsWith("/") && !relativePath.startsWith("/")) {
        combined += "/";
    }
    combined += relativePath;
    // Split into components
    String[] parts = combined.split("/");
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("..")) {
                stack.pollLast();
            } // else ignore; can't go above root
        } else {
            stack.addLast(part);
        }
    }
    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (absolute) {
        result.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }
    // If path is absolute and no components, return root "/"
    if (absolute && result.length() == 0) {
        result.append("/");
    }
    return result.toString();
}

