private void checkIfPackedField() throws IOException {
    /* 
     * In the Protocol Buffers wire format the packed repeated fields are encoded as a
     * length-delimited section that contains a concatenated sequence of the field values.
     * The presence of a packed field is signaled by the field descriptor (on the
     * message assembly side) and recognised by the parser once the wire type of the
     * current tag is LENGTH_DELIMITED (wire type 2).  This method inspects the
     * current field descriptor and the current wire type and updates the parser's
     * internal state to remember whether it is currently inside a packed field.
     *
     * If the wire type is not LENGTH_DELIMITED the packed flag is cleared.
     */
    try {
        // The tag already contains the field number and wire type.
        int wireType = currentTag & 0x7;
        if (wireType == WIRETYPE_LENGTH_DELIMITED && currentFieldDescriptor != null
                && currentFieldDescriptor.isPacked()) {
            // We are now reading a packed field; update internal flag.
            isReadingPackedField = true;
        } else {
            // Not a packed field.
            isReadingPackedField = false;
        }
    } catch (NullPointerException e) {
        // If currentFieldDescriptor or currentTag is null, the input stream might be
        // corrupted or not yet initialised.  Wrap and propagate as IOException.
        throw new IOException("Failed to determine packed field status", e);
    }
}

