public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (timeRanges == null || timeRanges.isEmpty()) {
        return result; // nothing to filter by, return empty list
    }
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            try {
                // Attempt to parse a snapshot from the line.  The actual
                // parsing logic depends on the format of the file
                ThreadSnapshot snapshot = ThreadSnapshot.parse(line); // assume a static parse method
                long timestamp = snapshot.getTimestamp(); // assume a getter
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    long start = range.getStartTime();
                    long end = range.getEndTime();
                    if (timestamp >= start && timestamp <= end) {
                        result.add(snapshot);
                        break;
                    }
                }
            } catch (Exception e) {
                // Ignore lines that cannot be parsed or snapshots that have no timestamp
            }
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            ThreadSnapshot ts;
            try {
                ts = ThreadSnapshot.parse(line);
            } catch (Exception e) {
                // Skip lines that cannot be parsed into a ThreadSnapshot
                continue;
            }
            if (ts == null) {
                continue;
            }
            if (timeRanges == null || timeRanges.isEmpty()) {
                snapshots.add(ts);
            } else {
                long tsTime = ts.getTimestamp();
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (tsTime >= range.getStartTime() && tsTime <= range.getEndTime()) {
                        snapshots.add(ts);
                        break;
                    }
                }
            }
        }
    }
    return snapshots;
