public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    if (file == null || !file.exists() || timeRanges == null || timeRanges.isEmpty()) {
        return result;
    }
    java.nio.file.Path path = file.toPath();
    java.util.List<String> lines = java.nio.file.Files.readAllLines(path);
    for (String line : lines) {
        if (line == null || line.trim().isEmpty()) {
            continue;
        }
        try {
            String[] parts = line.split("\\|", 2);
            long timestamp = Long.parseLong(parts[0].trim());
            String data = parts.length > 1 ? parts[1] : "";
            ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, data);
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                try {
                    if (range.contains(timestamp)) {
                        result.add(snapshot);
                        break;
                    }
                } catch (NoSuchMethodError | IllegalArgumentException e) {
                    // fallback if contains not available: assume range has getStartTime() and getEndTime()
                    java.lang.reflect.Method startMethod = range.getClass().getMethod("getStartTime");
                    java.lang.reflect.Method endMethod = range.getClass().getMethod("getEndTime");
                    long start = (long) startMethod.invoke(range);
                    long end = (long) endMethod.invoke(range);
                    if (timestamp >= start && timestamp <= end) {
                        result.add(snapshot);
                        break;
                    }
                }
            }
        } catch (Exception e) {
            // skip malformed line
        }
    }
    return result;
}

