        if (obj instanceof Collection<?>) {
            for (Object o : (Collection<?>) obj) {
                if (o instanceof ThreadSnapshot) {
                    ThreadSnapshot ts = (ThreadSnapshot) o;
                    if (timeRanges == null || timeRanges.isEmpty()) {
                        result.add(ts);
                    } else {
